// === Tab: mySketch ===
// attractor_3.0

let N = 1112 ; let M = 10 ; let R = 4 ;

let X[] = new Array(N) ; let Y[] = new Array(N) ; let dX[] = new Array(N) ; let dY[] = new Array(N) ;
let CX[] = new Array(M) ; let CY[] = new Array(M) ; let CR[] = new Array(M) ;
let I ; let II ; let L ; let KX ; let KY ; 


function setup(){

  createCanvas(1112, 834) ; noSmooth() ; background(0) ; //stroke(255,0,0) ; 
  colorMode(HSB, 255);
	stroke(255);
  for ( I = 0 ; I < N ; I++ ){
    KX = random(550,2000) ; KY = random(-PI,+PI) ;
    X[I] = KX*cos(KY) ; Y[I] = KX*sin(KY) ;
  }

  for ( I = 0 ; I < M ; I++ ){
    CR[I] = random(+60,+200) ; CX[I] = random(-width/2+CR[I],width/2-CR[I]) ; CY[I] = random(-height/2+CR[I],height/2-CR[I]) ; 		
  }

} // setup()


function draw(){
  noStroke();
  fill(0,0,0,20) ; rect(-1,-1,width+2,height+2) ; fill(255,0,0) ;
	translate(256, 117);
  stroke(255);
  for ( I = 0 ; I < N ; I++ ){
    for ( II = 0 ; II < M ; II++ ){
      KX = X[I]-CX[II] ; KY = Y[I]-CY[II] ;
      L = sqrt((KX*KX)+(KY*KY)) ;
      dX[I] = dX[I] + ((KX-KY-(KX*((KX*KX)+(KY*KY))/pow(CR[II],2)))/pow(L,5)) ;
      dY[I] = dY[I] + ((KX+KY-(KY*((KX*KX)+(KY*KY))/pow(CR[II],2)))/pow(L,5)) ;
    }
    for ( II = I+1 ; II < N ; II++ ){
      L = sqrt(pow(X[I]-X[II],2)+pow(Y[I]-Y[II],2)) ;
      if ( L < 2*R ){
         dX[I] =  dX[I] + ((X[I]-X[II])/L) ;  dY[I] =  dY[I] + ((Y[I]-Y[II])/L) ;
        dX[II] = dX[II] - ((X[I]-X[II])/L) ; dY[II] = dY[II] - ((Y[I]-Y[II])/L) ;
      }
    }
  }

  for ( I = 0 ; I < N ; I++ ){
    L = sqrt((dX[I]*dX[I])+(dY[I]*dY[I])) ;
    dX[I] = 2*dX[I]/L ; dY[I] = 2*dY[I]/L ;
		stroke(I/N*255, 200, 255);
		fill(I/N*255, 200, 200);
    ellipse(X[I]+300,Y[I]+300,R,R) ;
    X[I] = X[I] + dX[I] ; Y[I] = Y[I] + dY[I] ;
    dX[I] = 0 ; dY[I] = 0 ;
  }

} // draw()



function mousePressed(){
  save('logo2.png');
  for ( I = 0 ; I < M ; I++ ){
    CR[I] = random(+60,+200) ; CX[I] = random(-width/2+CR[I],width/2-CR[I]) ; CY[I] = random(-height/2+CR[I],height/2-CR[I]) ; 
  }

}// mousePressed()

